create extension if not exists pgcrypto;
create type public.community_role as enum ('member','moderator','owner');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,username text not null unique,display_name text not null default '',bio text not null default '',avatar_url text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint username_format check(username ~ '^[a-z0-9_]{3,24}$'),constraint display_name_length check(char_length(display_name)<=60),constraint bio_length check(char_length(bio)<=240));
create table public.communities(id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique,description text not null default '',created_by uuid references public.profiles(id) on delete set null,is_public boolean not null default true,created_at timestamptz not null default now(),constraint community_name_length check(char_length(name) between 2 and 60),constraint community_slug_format check(slug ~ '^[a-z0-9-]{3,40}$'));
create table public.community_members(community_id uuid not null references public.communities(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,role public.community_role not null default 'member',joined_at timestamptz not null default now(),primary key(community_id,user_id));
create table public.posts(id uuid primary key default gen_random_uuid(),author_id uuid not null references public.profiles(id) on delete cascade,community_id uuid references public.communities(id) on delete set null,body text not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,constraint post_body_length check(char_length(body) between 1 and 5000));
create table public.comments(id uuid primary key default gen_random_uuid(),post_id uuid not null references public.posts(id) on delete cascade,author_id uuid not null references public.profiles(id) on delete cascade,body text not null,created_at timestamptz not null default now(),deleted_at timestamptz,constraint comment_body_length check(char_length(body) between 1 and 3000));
create table public.reactions(id uuid primary key default gen_random_uuid(),post_id uuid not null references public.posts(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,kind text not null default 'like' check(kind='like'),created_at timestamptz not null default now(),unique(post_id,user_id));
create table public.follows(follower_id uuid not null references public.profiles(id) on delete cascade,followed_id uuid not null references public.profiles(id) on delete cascade,created_at timestamptz not null default now(),primary key(follower_id,followed_id),check(follower_id<>followed_id));
create table public.user_blocks(blocker_id uuid not null references public.profiles(id) on delete cascade,blocked_id uuid not null references public.profiles(id) on delete cascade,created_at timestamptz not null default now(),primary key(blocker_id,blocked_id),check(blocker_id<>blocked_id));
create table public.reports(id uuid primary key default gen_random_uuid(),reporter_id uuid not null references public.profiles(id) on delete cascade,target_type text not null check(target_type in ('post','comment','profile')),target_id uuid not null,reason text not null,details text not null default '',status text not null default 'open' check(status in ('open','reviewing','resolved','dismissed')),created_at timestamptz not null default now(),check(char_length(reason) between 2 and 100),check(char_length(details)<=2000));
create index posts_created_idx on public.posts(created_at desc) where deleted_at is null;
create index comments_post_idx on public.comments(post_id,created_at) where deleted_at is null;
create index reactions_post_idx on public.reactions(post_id);
create index community_members_user_idx on public.community_members(user_id,joined_at desc);

create schema if not exists private;
revoke all on schema private from public,anon,authenticated;
create or replace function private.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$ declare raw_name text; base_name text; begin raw_name:=coalesce(new.raw_user_meta_data->>'username',split_part(coalesce(new.email,''),'@',1),'user');base_name:=left(regexp_replace(lower(raw_name),'[^a-z0-9_]','','g'),16);if char_length(base_name)<3 then base_name:='user';end if;insert into public.profiles(id,username,display_name,avatar_url) values(new.id,base_name||'_'||left(new.id::text,6),left(coalesce(new.raw_user_meta_data->>'display_name',new.raw_user_meta_data->>'full_name',new.raw_user_meta_data->>'name',split_part(coalesce(new.email,'COMMON member'),'@',1)),60),new.raw_user_meta_data->>'avatar_url') on conflict(id) do nothing;return new;end $$;
revoke all on function private.handle_new_user() from public,anon,authenticated;
create trigger on_auth_user_created after insert on auth.users for each row execute function private.handle_new_user();

alter table public.profiles enable row level security;alter table public.communities enable row level security;alter table public.community_members enable row level security;alter table public.posts enable row level security;alter table public.comments enable row level security;alter table public.reactions enable row level security;alter table public.follows enable row level security;alter table public.user_blocks enable row level security;alter table public.reports enable row level security;
create policy "public profile read" on public.profiles for select to anon,authenticated using(true);
create policy "own profile insert" on public.profiles for insert to authenticated with check(id=(select auth.uid()));
create policy "own profile update" on public.profiles for update to authenticated using(id=(select auth.uid())) with check(id=(select auth.uid()));
revoke select on public.profiles from anon,authenticated;grant select(id,username,display_name,bio,avatar_url,created_at) on public.profiles to anon,authenticated;grant insert(id,username,display_name,bio,avatar_url) on public.profiles to authenticated;grant update(username,display_name,bio,avatar_url,updated_at) on public.profiles to authenticated;
create policy "public communities read" on public.communities for select to anon,authenticated using(is_public=true);
create policy "public membership read" on public.community_members for select to authenticated using(user_id=(select auth.uid()) or exists(select 1 from public.communities c where c.id=community_id and c.is_public));
create policy "join public communities" on public.community_members for insert to authenticated with check(user_id=(select auth.uid()) and role='member' and exists(select 1 from public.communities c where c.id=community_id and c.is_public));
create policy "leave own communities" on public.community_members for delete to authenticated using(user_id=(select auth.uid()) and role='member');
create policy "read visible posts" on public.posts for select to anon,authenticated using(deleted_at is null and (community_id is null or exists(select 1 from public.communities c where c.id=community_id and c.is_public)));
create policy "create own posts" on public.posts for insert to authenticated with check(author_id=(select auth.uid()) and deleted_at is null and (community_id is null or exists(select 1 from public.communities c where c.id=community_id and c.is_public) or exists(select 1 from public.community_members cm where cm.community_id=posts.community_id and cm.user_id=(select auth.uid()))));
create policy "update own posts" on public.posts for update to authenticated using(author_id=(select auth.uid()) and deleted_at is null) with check(author_id=(select auth.uid()));
create policy "read visible comments" on public.comments for select to anon,authenticated using(deleted_at is null and exists(select 1 from public.posts p where p.id=post_id and p.deleted_at is null));
create policy "create own comments" on public.comments for insert to authenticated with check(author_id=(select auth.uid()) and deleted_at is null and exists(select 1 from public.posts p where p.id=post_id and p.deleted_at is null));
create policy "update own comments" on public.comments for update to authenticated using(author_id=(select auth.uid()) and deleted_at is null) with check(author_id=(select auth.uid()));
create policy "read reactions" on public.reactions for select to anon,authenticated using(true);
create policy "react as self" on public.reactions for insert to authenticated with check(user_id=(select auth.uid()) and exists(select 1 from public.posts p where p.id=post_id and p.deleted_at is null));
create policy "remove own reactions" on public.reactions for delete to authenticated using(user_id=(select auth.uid()));
create policy "read own follows" on public.follows for select to authenticated using(follower_id=(select auth.uid()) or followed_id=(select auth.uid()));
create policy "follow as self" on public.follows for insert to authenticated with check(follower_id=(select auth.uid()) and follower_id<>followed_id);
create policy "unfollow as self" on public.follows for delete to authenticated using(follower_id=(select auth.uid()));
create policy "read own blocks" on public.user_blocks for select to authenticated using(blocker_id=(select auth.uid()));
create policy "block as self" on public.user_blocks for insert to authenticated with check(blocker_id=(select auth.uid()) and blocker_id<>blocked_id);
create policy "unblock as self" on public.user_blocks for delete to authenticated using(blocker_id=(select auth.uid()));
-- Reports have RLS enabled and no client-facing policies: submission/review needs a validated server workflow.
